            double wavelength = 600 * Math.Pow(10, -9); // nm in Meter umrechnen
            double speedOfLight = 299792458;
            double planckConstant = 6.62607004 * Math.Pow(10, -34);

            // Energie eines Photons mit einer Wellenlänge von 600 nm berechnen
            double energy = (planckConstant * speedOfLight) / wavelength;

            // Plancksche Konstante berechnen
