import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

public class FlowerCategorizer {

    public static void main(String[] args) {
        String[] flowers = {"Lilac", "Daisy", "Marigold", "Chrysanthemum"};
        Map<String, Set<String>> categories = new TreeMap<>();

        // Define category extraction method
        String extractCategory(String flower) {
            switch (flower.substring(0, 1).toUpperCase()) {
                case "L":
                    return "Lilac";
                case "D":
                    return "Daisy";
                case "M":
                    return "Marigold";
                case "C":
                    return "Chrysanthemum";
                default:
                    // Add special cases if needed
                    return "";
            }
        }

        // Populate categories map
        for (String flower : flowers) {
            String category = extractCategory(flower);
            if (!category.isEmpty()) {
                Set<String> flowerSet = categories.computeIfAbsent(category, key -> new HashSet<>());
                flowerSet.add(flower);
            }
        }

        // Print categories in alphabetical order
        for (Map.Entry<String, Set<String>> entry : categories.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }
    }

}
```

